// Deterministic checker: read Kubernetes manifest YAML (one or more
// `---`-separated documents) and flag every `apiVersion`+`kind` pair that a
// past Kubernetes release has already removed, or will remove at a target
// version you name. No network call, no kubeconfig, no API server -- it
// reads only the text you give it.
//
// Why this is worth a dedicated check: a removed `apiVersion` is not a
// warning at apply time, it is a hard failure -- `kubectl apply` or a
// rolling `helm upgrade` returns `no matches for kind "X" in version "Y"`
// and stops, mid-upgrade, on a manifest that had applied cleanly on every
// prior cluster version. The Kubernetes project deprecates an API version
// for one or more full minor releases before removing it (its own
// deprecation policy guarantees at least that), which is exactly the window
// this check exists to use -- catch the manifest before the removal lands
// on a cluster you control, not during it.
//
// The table below is deliberately conservative: it lists only removals
// Kubernetes' own "Deprecated API Migration Guide" documents with a fixed
// release number, not every current beta or every future-dated proposal.
// See README.md for the source and the exact scope.

/**
 * Each entry: one `apiVersion` + one or more `kind`s that share a removal
 * release and a replacement. `removedIn` is the Kubernetes minor version
 * (e.g. "1.22") in which `kubectl`/the API server stopped accepting the old
 * `apiVersion` for that `kind` -- sourced from Kubernetes' own deprecated
 * API migration guide, not inferred.
 */
export const DEPRECATED_APIS = [
  {
    apiVersion: "extensions/v1beta1",
    kinds: ["DaemonSet", "Deployment", "ReplicaSet"],
    removedIn: "1.16",
    replacement: { apiVersion: "apps/v1" },
  },
  {
    apiVersion: "extensions/v1beta1",
    kinds: ["NetworkPolicy"],
    removedIn: "1.16",
    replacement: { apiVersion: "networking.k8s.io/v1" },
  },
  {
    apiVersion: "extensions/v1beta1",
    kinds: ["PodSecurityPolicy"],
    removedIn: "1.16",
    replacement: { apiVersion: "policy/v1beta1" },
    note: "policy/v1beta1 PodSecurityPolicy was itself removed with no direct replacement in 1.25 -- see that row below. Migrate straight to Pod Security Admission or a policy engine (e.g. Kyverno, OPA Gatekeeper) rather than the intermediate version.",
  },
  {
    apiVersion: "extensions/v1beta1",
    kinds: ["Ingress"],
    removedIn: "1.22",
    replacement: { apiVersion: "networking.k8s.io/v1" },
    note: "Ingress stayed available under extensions/v1beta1 for six releases after its apps/v1 siblings were removed -- do not assume every extensions/v1beta1 kind left on the same release.",
  },
  {
    apiVersion: "apps/v1beta1",
    kinds: ["Deployment", "StatefulSet"],
    removedIn: "1.16",
    replacement: { apiVersion: "apps/v1" },
  },
  {
    apiVersion: "apps/v1beta2",
    kinds: ["Deployment", "StatefulSet", "DaemonSet", "ReplicaSet"],
    removedIn: "1.16",
    replacement: { apiVersion: "apps/v1" },
  },
  {
    apiVersion: "networking.k8s.io/v1beta1",
    kinds: ["Ingress", "IngressClass"],
    removedIn: "1.22",
    replacement: { apiVersion: "networking.k8s.io/v1" },
  },
  {
    apiVersion: "rbac.authorization.k8s.io/v1alpha1",
    kinds: ["ClusterRole", "ClusterRoleBinding", "Role", "RoleBinding"],
    removedIn: "1.22",
    replacement: { apiVersion: "rbac.authorization.k8s.io/v1" },
  },
  {
    apiVersion: "rbac.authorization.k8s.io/v1beta1",
    kinds: ["ClusterRole", "ClusterRoleBinding", "Role", "RoleBinding"],
    removedIn: "1.22",
    replacement: { apiVersion: "rbac.authorization.k8s.io/v1" },
  },
  {
    apiVersion: "apiextensions.k8s.io/v1beta1",
    kinds: ["CustomResourceDefinition"],
    removedIn: "1.22",
    replacement: { apiVersion: "apiextensions.k8s.io/v1" },
  },
  {
    apiVersion: "apiregistration.k8s.io/v1beta1",
    kinds: ["APIService"],
    removedIn: "1.22",
    replacement: { apiVersion: "apiregistration.k8s.io/v1" },
  },
  {
    apiVersion: "authentication.k8s.io/v1beta1",
    kinds: ["TokenReview"],
    removedIn: "1.22",
    replacement: { apiVersion: "authentication.k8s.io/v1" },
  },
  {
    apiVersion: "authorization.k8s.io/v1beta1",
    kinds: [
      "LocalSubjectAccessReview",
      "SelfSubjectAccessReview",
      "SelfSubjectRulesReview",
      "SubjectAccessReview",
    ],
    removedIn: "1.22",
    replacement: { apiVersion: "authorization.k8s.io/v1" },
  },
  {
    apiVersion: "certificates.k8s.io/v1beta1",
    kinds: ["CertificateSigningRequest"],
    removedIn: "1.22",
    replacement: { apiVersion: "certificates.k8s.io/v1" },
  },
  {
    apiVersion: "coordination.k8s.io/v1beta1",
    kinds: ["Lease"],
    removedIn: "1.22",
    replacement: { apiVersion: "coordination.k8s.io/v1" },
  },
  {
    apiVersion: "scheduling.k8s.io/v1alpha1",
    kinds: ["PriorityClass"],
    removedIn: "1.22",
    replacement: { apiVersion: "scheduling.k8s.io/v1" },
  },
  {
    apiVersion: "scheduling.k8s.io/v1beta1",
    kinds: ["PriorityClass"],
    removedIn: "1.22",
    replacement: { apiVersion: "scheduling.k8s.io/v1" },
  },
  {
    apiVersion: "storage.k8s.io/v1beta1",
    kinds: ["CSIDriver", "CSINode", "StorageClass", "VolumeAttachment"],
    removedIn: "1.22",
    replacement: { apiVersion: "storage.k8s.io/v1" },
  },
  {
    apiVersion: "policy/v1beta1",
    kinds: ["PodDisruptionBudget"],
    removedIn: "1.25",
    replacement: { apiVersion: "policy/v1" },
  },
  {
    apiVersion: "policy/v1beta1",
    kinds: ["PodSecurityPolicy"],
    removedIn: "1.25",
    replacement: null,
    note: "PodSecurityPolicy was removed outright with no direct successor resource. Migrate to the built-in Pod Security Admission controller (namespace labels) or a policy engine such as Kyverno or OPA Gatekeeper.",
  },
  {
    apiVersion: "batch/v1beta1",
    kinds: ["CronJob"],
    removedIn: "1.25",
    replacement: { apiVersion: "batch/v1" },
  },
  {
    apiVersion: "discovery.k8s.io/v1beta1",
    kinds: ["EndpointSlice"],
    removedIn: "1.25",
    replacement: { apiVersion: "discovery.k8s.io/v1" },
  },
  {
    apiVersion: "events.k8s.io/v1beta1",
    kinds: ["Event"],
    removedIn: "1.25",
    replacement: { apiVersion: "events.k8s.io/v1" },
  },
  {
    apiVersion: "autoscaling/v2beta1",
    kinds: ["HorizontalPodAutoscaler"],
    removedIn: "1.25",
    replacement: { apiVersion: "autoscaling/v2" },
  },
  {
    apiVersion: "autoscaling/v2beta2",
    kinds: ["HorizontalPodAutoscaler"],
    removedIn: "1.26",
    replacement: { apiVersion: "autoscaling/v2" },
  },
];

const LOOKUP = new Map();
for (const entry of DEPRECATED_APIS) {
  for (const kind of entry.kinds) {
    LOOKUP.set(`${entry.apiVersion}�${kind}`, entry);
  }
}

/** Finds a table entry for an exact apiVersion+kind pair, or undefined. */
export function findEntry(apiVersion, kind) {
  return LOOKUP.get(`${apiVersion}�${kind}`);
}

/**
 * Parses a Kubernetes minor version out of strings like "1.22", "v1.22.4",
 * or "1.22.0-eks-1234abc". Returns { major, minor } or null if nothing
 * version-shaped is found.
 */
export function parseVersion(input) {
  const m = /^v?(\d+)\.(\d+)/.exec(String(input ?? "").trim());
  if (!m) return null;
  return { major: Number(m[1]), minor: Number(m[2]) };
}

/** -1 if a<b, 0 if equal, 1 if a>b. Throws if either fails to parse. */
export function compareVersions(a, b) {
  const va = parseVersion(a);
  const vb = parseVersion(b);
  if (!va || !vb) throw new Error(`not a Kubernetes version like "1.22": ${!va ? a : b}`);
  if (va.major !== vb.major) return va.major < vb.major ? -1 : 1;
  if (va.minor !== vb.minor) return va.minor < vb.minor ? -1 : 1;
  return 0;
}

// --- YAML document splitting & header extraction --------------------------
//
// This is not a general YAML parser -- it reads only the two fields this
// check needs (`apiVersion`, `kind`) plus `metadata.name` for the report,
// each as a plain top-level (or, for `name`, one-level-nested) key. That is
// enough for an ordinary manifest file and deliberately does not attempt to
// evaluate Helm template expressions or Kustomize patches -- run this
// against the final rendered manifest (`helm template`, `kustomize build`)
// for those, not the source templates. See README.md.

/** Splits a multi-document YAML file on a line that is exactly `---`. */
export function splitDocuments(text) {
  const raw = String(text ?? "");
  return raw
    .split(/^\s*---\s*$/m)
    .map((doc) => doc.replace(/^﻿/, ""))
    .filter((doc) => doc.replace(/#.*$/gm, "").trim().length > 0);
}

function extractTopLevel(doc, key) {
  const re = new RegExp(`^${key}:[ \\t]*['"]?([^'"\\n#]+?)['"]?[ \\t]*(#.*)?$`, "m");
  const m = re.exec(doc);
  return m ? m[1].trim() : null;
}

function extractName(doc) {
  // Capture every line right after a top-level `metadata:` that is itself
  // indented (part of that block) -- stops at the first line that starts a
  // new top-level key (or the end of the document).
  const m = /^metadata:[ \t]*\n((?:[ \t]+[^\n]*\n?)*)/m.exec(`${doc}\n`);
  const block = m ? m[1] : doc; // fall back to scanning the whole doc
  const nameMatch = /^[ \t]+name:[ \t]*['"]?([^'"\n#]+?)['"]?[ \t]*(#.*)?$/m.exec(block);
  return nameMatch ? nameMatch[1].trim() : null;
}

/**
 * Reads one manifest document's identifying fields. Returns null if it has
 * no `apiVersion` or `kind` at all (a blank document, a `List`, a
 * Kustomize/Helm partial) -- that is not an error, just nothing to check.
 */
export function readManifestHeader(doc) {
  const apiVersion = extractTopLevel(doc, "apiVersion");
  const kind = extractTopLevel(doc, "kind");
  if (!apiVersion || !kind) return null;
  return { apiVersion, kind, name: extractName(doc) };
}

/** Parses every document in a manifest file into header descriptors. */
export function parseManifests(text) {
  const docs = splitDocuments(text);
  if (docs.length === 0) throw new Error("no YAML documents found in the input");
  return docs.map((doc, index) => ({ index, header: readManifestHeader(doc) }));
}

/**
 * Checks parsed manifests against the deprecation table.
 *
 * Without `targetVersion`, every match is reported as `status: "known"` --
 * it is a documented removal at *some* release, worth surfacing regardless
 * of which cluster you run today. With `targetVersion`, each match is
 * classified `"removed"` (the target release no longer accepts it -- this
 * manifest will fail to apply) or `"deprecated"` (still accepted at the
 * target, but a later, named release will refuse it).
 */
export function checkManifests(manifests, { targetVersion = null } = {}) {
  const findings = [];
  let checked = 0;
  for (const { index, header } of manifests) {
    if (!header) continue;
    checked += 1;
    const entry = findEntry(header.apiVersion, header.kind);
    if (!entry) continue;
    let status = "known";
    if (targetVersion) {
      status = compareVersions(targetVersion, entry.removedIn) >= 0 ? "removed" : "deprecated";
    }
    findings.push({
      index,
      apiVersion: header.apiVersion,
      kind: header.kind,
      name: header.name ?? "(unnamed)",
      removedIn: entry.removedIn,
      replacement: entry.replacement,
      note: entry.note ?? null,
      status,
    });
  }
  return { manifestsChecked: checked, documentsChecked: manifests.length, findings, targetVersion };
}

